    "code": "import numpy as np\n\ndef make_spiral(n=100, k=3, seed=0):\n    rng = np.random.default_rng(seed)\n    X = np.zeros((n * k, 2))\n    y = np.zeros(n * k, dtype=int)\n    for c in range(k):\n        r = np.linspace(0.0, 1, n)\n        t = np.linspace(c * 4, (c + 1) * 4, n) + rng.normal(0, 0.2, n)\n        X[c * n:(c + 1) * n] = np.c_[r * np.sin(t), r * np.cos(t)]\n        y[c * n:(c + 1) * n] = c\n    return X, y\n\ndef init(d_in, d_hidden, d_out, seed=0):\n    rng = np.random.default_rng(seed)\n    return {\"W1\": rng.normal(0, np.sqrt(2 / d_in), (d_in, d_hidden)),\n            \"b1\": np.full(d_hidden, 0.01),\n            \"W2\": rng.normal(0, np.sqrt(2 / d_hidden), (d_hidden, d_out)),\n            \"b2\": np.zeros(d_out)}\n\ndef forward(p, X):\n    z1 = X @ p[\"W1\"] + p[\"b1\"]\n    h = np.maximum(z1, 0)\n    scores = h @ p[\"W2\"] + p[\"b2\"]\n    return z1, h, scores\n",
