    "code": "def train_one_epoch(model, dl, optimizer, loss_fn, device):\n    model.train()\n    total, n = 0.0, 0\n    for xb, yb in dl:\n        xb, yb = xb.to(device), yb.to(device)\n        optimizer.zero_grad()\n        out = model(xb)\n        loss = loss_fn(out, yb)\n        loss.backward()\n        optimizer.step()\n        total += loss.item() * len(yb)\n        n += len(yb)\n    return total / n\n\n@torch.no_grad()\ndef evaluate(model, dl, loss_fn, device):\n    model.eval()\n    total, correct, n = 0.0, 0, 0\n    for xb, yb in dl:\n        xb, yb = xb.to(device), yb.to(device)\n        out = model(xb)\n        total += loss_fn(out, yb).item() * len(yb)\n        correct += (out.argmax(dim=1) == yb).sum().item()\n        n += len(yb)\n    return total / n, correct / n\n\nloss_fn = nn.CrossEntropyLoss()\n",
