   "metrics.py": "# metrics.py — the project of module 2, chapter 12 (sections 12.2 and 10.2)\nimport numpy as np\n\ndef confusion_matrix(y_true, y_pred, k):\n    cm = np.zeros((k, k), dtype=int)\n    np.add.at(cm, (y_true, y_pred), 1)\n    return cm\n\ndef per_class_report(cm, names):\n    tp = np.diag(cm).astype(float)\n    precision = tp / np.maximum(cm.sum(axis=0), 1)\n    recall = tp / np.maximum(cm.sum(axis=1), 1)\n    f1 = 2 * precision * recall / np.maximum(precision + recall, 1e-12)\n    print(f\"{'class':>8} {'prec':>6} {'rec':>6} {'f1':>6} {'n':>5}\")\n    for i, nm in enumerate(names):\n        print(f\"{nm:>8} {precision[i]:6.3f} {recall[i]:6.3f} {f1[i]:6.3f} {cm[i].sum():5d}\")\n    print(f\"{'acc':>8} {tp.sum() / cm.sum():6.3f}   macro-f1 {f1.mean():.3f}\")\n    return precision, recall, f1\n\n\nclass EarlyStopping:\n    def __init__(self, patience=5, min_delta=1e-4, mode=\"max\"):\n        self.patience, self.min_delta, self.mode = patience, min_delta, mode\n        self.best, self.bad = None, 0\n\n    def step(self, value):\n        if self.best is None:\n            improved = True\n        elif self.mode == \"max\":\n            improved = value > self.best + self.min_delta\n        else:\n            improved = value < self.best - self.min_delta\n        if improved:\n            self.best, self.bad = value, 0\n        else:\n            self.bad += 1\n        return improved, self.bad >= self.patience\n\n\nimport json, csv, hashlib, time\nfrom pathlib import Path\n\ndef run_hash(cfg):\n    s = json.dumps(cfg, sort_keys=True)\n    return hashlib.sha1(s.encode()).hexdigest()[:8]\n\nclass RunLogger:\n    def __init__(self, root, cfg):\n        self.dir = Path(root) / f\"{time.strftime('%Y%m%d-%H%M%S')}_{run_hash(cfg)}\"\n        self.dir.mkdir(parents=True, exist_ok=True)\n        (self.dir / \"config.json\").write_text(json.dumps(cfg, indent=2, sort_keys=True))\n        self.rows = []\n\n    def log(self, **metrics):\n        self.rows.append(metrics)\n        with open(self.dir / \"metrics.csv\", \"w\", newline=\"\") as f:\n            w = csv.DictWriter(f, fieldnames=list(self.rows[0].keys()))\n            w.writeheader()\n            w.writerows(self.rows)\n"
